const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let token=localStorage.getItem('essenceWorkspaceToken'), me=null, demo=false, view='control';
let enginePoll=0,programStreamTimer=0,programStreamActive=false,programStreamRecorder=null,programStreamChunks=0,programChunkQueue=Promise.resolve();
let audioCtx=null, micGain=null, micMeter=null, processedMic=null, previewCameraVideo=null, previewScreenVideo=null, previewRaf=0, programScreenVideo=null;
const state={camera:null,screen:null,media:null,program:'camera',preview:'camera',graphics:null,recording:null,recorder:null,recordChunks:[],programVideo:null,programCanvas:null,raf:0,scenes:[{id:'camera',name:'Camera 1',source:'camera',desc:'Full-frame presenter'},{id:'pip',name:'Camera + Screen',source:'pip',desc:'Screen with presenter picture-in-picture'},{id:'screen',name:'Screen Share',source:'screen',desc:'Full-frame presentation'},{id:'media',name:'Media Roll',source:'media',desc:'Play a video package'}],cues:[{n:1,name:'Open / Camera 1',source:'camera',status:'READY'},{n:2,name:'Lower Third',source:'graphic',status:'STANDBY'},{n:3,name:'Roll Package',source:'media',status:'STANDBY'},{n:4,name:'Back to Camera',source:'camera',status:'STANDBY'}]};
async function api(path,opt={}){const h={...(opt.headers||{})};if(!(opt.body instanceof FormData))h['Content-Type']='application/json';if(token)h.Authorization='Bearer '+token;const r=await fetch('/api'+path,{...opt,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Request failed');return d}
function toast(m,bad=false){const x=document.createElement('div');x.className='toast';x.textContent=m;$('#toastHost').appendChild(x);setTimeout(()=>x.remove(),2500)}
function esc(x){return String(x??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function showLogin(){$('#loginScreen').hidden=false;$('#app').hidden=true}
function showApp(){ $('#loginScreen').hidden=true;$('#app').hidden=false;$('#userBadge').textContent=me?.email||'Demo Operator'; $('#modePill').textContent=demo?'LOCAL DEMO':'CONNECTED'; }
async function login(){try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value.trim(),password:$('#password').value})});token=d.token;me=d.user;localStorage.setItem('essenceWorkspaceToken',token);demo=false;showApp();openView('control')}catch(e){$('#loginMsg').textContent=e.message}}
function openDemo(){demo=true;me={email:'demo@essence.local',role:'operator'};showApp();openView('control');toast('Local demo studio ready')}
async function start(){if(token){try{me=(await api('/auth/me')).user;demo=false;showApp();openView('control');return}catch{localStorage.removeItem('essenceWorkspaceToken');token=null}}showLogin()}
function setHealth(ok=true,msg='Production engine ready'){$('#health').className='health '+(ok?'ok':'warn');$('#health').textContent=ok?'● READY':'● CHECK';$('#signalText').textContent=msg}
function streamFor(type){if(type==='camera')return state.camera;if(type==='screen')return state.screen;return null}
function previewSource(type){const v=$('#previewVideo');if(!v)return;const stream=streamFor(type);if(stream){v.srcObject=stream;v.removeAttribute('src');v.play().catch(()=>{})}else if(type==='media'&&state.mediaUrl){v.srcObject=null;v.src=state.mediaUrl;v.controls=false;v.play().catch(()=>{})}else{v.srcObject=null;v.removeAttribute('src');v.pause()}}
function updatePreviewGraphic(){const el=$('#previewGraphic');if(!el)return;const g=state.graphics;if(!g||!g.onAir){el.hidden=true;el.innerHTML='';return}el.hidden=false;el.innerHTML=`<strong>${esc(g.headline||'')}</strong><small>${esc(g.sub||'')}</small>`}
function renderMonitor(){
 const p=$('#programVideo');
 if(p){
   const stream=state.program==='pip'?state.camera:streamFor(state.program);
   if(stream){p.srcObject=stream;p.removeAttribute('src');p.play().catch(()=>{})}
   else if(state.program==='media'&&state.mediaUrl){p.srcObject=null;p.src=state.mediaUrl;p.play().catch(()=>{})}
   else{p.srcObject=null;p.removeAttribute('src');p.pause()}
 }
 const pv=$('#previewVideo');
 if(pv){
   const pc=$('#previewCanvas');if(pc)pc.hidden=state.preview!=='pip';pv.hidden=state.preview==='pip';
   const stream=streamFor(state.preview);
   if(stream){pv.hidden=false;pv.srcObject=stream;pv.removeAttribute('src');pv.play().catch(()=>{})}
   else if(state.preview==='media'&&state.mediaUrl){pv.hidden=false;pv.srcObject=null;pv.src=state.mediaUrl;pv.play().catch(()=>{})}
   else{pv.srcObject=null;pv.removeAttribute('src');pv.pause();pv.hidden=state.preview==='pip'}
 }
 if($('#programCanvas')) startProgramRenderer();
 if($('#previewCanvas')) startPreviewRenderer();
 updatePreviewGraphic();
}
function fitDraw(ctx,video,x,y,w,h){if(!video||video.readyState<2)return;const vw=video.videoWidth||1280,vh=video.videoHeight||720,scale=Math.max(w/vw,h/vh),dw=vw*scale,dh=vh*scale;ctx.drawImage(video,x+(w-dw)/2,y+(h-dh)/2,dw,dh)}
function startPreviewRenderer(){const canvas=$('#previewCanvas');if(!canvas)return;cancelAnimationFrame(previewRaf);canvas.width=1280;canvas.height=720;const ctx=canvas.getContext('2d');previewCameraVideo=previewCameraVideo||document.createElement('video');previewScreenVideo=previewScreenVideo||document.createElement('video');previewCameraVideo.muted=true;previewCameraVideo.autoplay=true;previewScreenVideo.muted=true;previewScreenVideo.autoplay=true;if(state.camera&&previewCameraVideo.srcObject!==state.camera)previewCameraVideo.srcObject=state.camera;if(state.screen&&previewScreenVideo.srcObject!==state.screen)previewScreenVideo.srcObject=state.screen;const draw=()=>{ctx.fillStyle='#03060d';ctx.fillRect(0,0,1280,720);if(state.preview==='pip'){if(state.camera)fitDraw(ctx,previewCameraVideo,0,0,1280,720);if(state.screen){fitDraw(ctx,previewScreenVideo,720,405,500,280);ctx.strokeStyle='#8b5cf6';ctx.lineWidth=5;ctx.strokeRect(720,405,500,280)}}previewRaf=requestAnimationFrame(draw)};draw()}
function startProgramRenderer(){const canvas=$('#programCanvas');const video=$('#programVideo');if(!canvas||!video)return;state.programCanvas=canvas;state.programVideo=video;cancelAnimationFrame(state.raf);canvas.width=1280;canvas.height=720;const ctx=canvas.getContext('2d');const draw=()=>{ctx.fillStyle='#03060d';ctx.fillRect(0,0,1280,720);if(state.program==='pip'){fitDraw(ctx,video,0,0,1280,720);if(state.screen){programScreenVideo=programScreenVideo||document.createElement('video');programScreenVideo.muted=true;programScreenVideo.autoplay=true;if(programScreenVideo.srcObject!==state.screen)programScreenVideo.srcObject=state.screen;programScreenVideo.play().catch(()=>{});fitDraw(ctx,programScreenVideo,720,405,500,280);ctx.strokeStyle='#8b5cf6';ctx.lineWidth=5;ctx.strokeRect(720,405,500,280)}}else if(state.program!=='none'){fitDraw(ctx,video,0,0,1280,720)}if(state.graphics&&state.graphics.onAir){ctx.fillStyle='rgba(8,16,33,.92)';ctx.fillRect(70,590,1140,82);ctx.fillStyle='#8b5cf6';ctx.fillRect(70,590,5,82);ctx.fillStyle='#fff';ctx.font='700 34px system-ui';ctx.fillText(String(state.graphics.headline||''),98,625);ctx.fillStyle='#a9b6d1';ctx.font='20px system-ui';ctx.fillText(String(state.graphics.sub||''),98,654)}state.raf=requestAnimationFrame(draw)};draw()}
async function take(){state.program=state.preview;renderMonitor();toast(`TAKE — ${state.program.toUpperCase()}`);setHealth(true,'Program output updated');if(programStreamActive)toast('Program feed updated live')}
function clearProgram(){state.program='none';renderMonitor();toast('Program cleared')}
async function enableCamera(){try{const raw=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});state.rawCamera=raw;const tracks=[...raw.getVideoTracks()];if(raw.getAudioTracks().length){audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')await audioCtx.resume();const src=audioCtx.createMediaStreamSource(raw);micGain=audioCtx.createGain();micGain.gain.value=1;micMeter=audioCtx.createAnalyser();micMeter.fftSize=256;processedMic=audioCtx.createMediaStreamDestination();src.connect(micGain);micGain.connect(micMeter);micGain.connect(processedMic);tracks.push(...processedMic.stream.getAudioTracks());}state.camera=new MediaStream(tracks);state.preview='camera';renderMonitor();toast('Camera + microphone connected');setHealth(true,'Camera + mic online')}catch(e){toast('Camera access failed: '+e.message,true);setHealth(false,'Camera permission required')}}
async function enableScreen(){try{state.screen=await navigator.mediaDevices.getDisplayMedia({video:true,audio:true});state.preview='screen';renderMonitor();toast('Screen share connected');setHealth(true,'Screen source online');state.screen.getVideoTracks()[0].addEventListener('ended',()=>{state.screen=null;renderMonitor();toast('Screen share ended')})}catch(e){toast('Screen share cancelled',true)}}
function loadMedia(file){if(!file)return;if(state.mediaUrl)URL.revokeObjectURL(state.mediaUrl);state.mediaUrl=URL.createObjectURL(file);state.media=null;state.preview='media';renderMonitor();toast('Media loaded: '+file.name);}
async function loadBroadcastState(){
 if(demo) return {channels:[{id:1,name:'Essence Network',channel_number:'01',call_sign:'ESSENCE',service_type:'television',video_format:'1080p25',audio_format:'stereo',transmission_output:'Primary broadcast output'}],rows:[{channel:{id:1,name:'Essence Network',channel_number:'01',call_sign:'ESSENCE',service_type:'television',video_format:'1080p25',audio_format:'stereo',transmission_output:'Primary broadcast output'},state:{status:'standby'},master:{mode:'scheduled',automation_enabled:1}}]};
 try{const d=await api('/workspace/master-control'); if(Array.isArray(d)) return {channels:d.map(x=>x.channel),rows:d}; return d}catch{return {channels:[],states:[],master:[],rows:[]}}
}
function broadcastServiceCard(x){const c=x.channel||{},st=x.state||{},m=x.master||{};return `<div class="service-card"><div><span class="eyebrow">TV SERVICE</span><h3>${esc(c.channel_number||'—')} • ${esc(c.name||'Unnamed')}</h3><p class="muted">${esc(c.call_sign||'No call sign')} • ${esc(c.video_format||'HD')} • ${esc(c.audio_format||'stereo')}</p></div><div class="service-state ${st.status==='live'?'live':''}">${esc(String(st.status||'offline').toUpperCase())}</div><div class="service-actions"><button class="ghost" data-master-preview="${c.id}">PREVIEW</button><button class="primary" data-master-take="${c.id}">TAKE TO AIR</button><button class="danger" data-master-stop="${c.id}">STOP</button></div><div class="small-note">Transmission: ${esc(c.transmission_output||'Not configured')} · Automation: ${m.automation_enabled?'ON':'OFF'}</div></div>`}
async function masterControl(){
 const d=await loadBroadcastState();
 const services=d.rows||[];
 $('#content').innerHTML=`<div class="page-head"><div><span class="eyebrow">ESSENCE NETWORK • MASTER CONTROL</span><h2>TV Broadcast Master Control</h2><p class="muted">Operate television services, automation and transmission outputs. The website is only an optional simulcast destination.</p></div><span class="status live">BROADCAST CONTROL</span></div><div class="notice">PRIMARY: studio / master control → programme playout → graphics → transmission chain. WEB SIMULCAST is secondary.</div><div class="service-grid">${services.map(broadcastServiceCard).join('')||'<div class="panel"><h3>No TV services</h3><p class="muted">Create a TV service in Control Centre.</p></div>'}</div><div class="panel"><h3>Station outputs</h3><div class="output-grid"><div><b>Programme</b><span>Master programme bus</span></div><div><b>Graphics</b><span>Key/fill or compositor layer</span></div><div><b>Audio</b><span>Master stereo programme</span></div><div><b>Transmission</b><span>SDI / NDI / IP encoder bridge</span></div></div><p class="small-note">Hardware transmission requires a local broadcast I/O or encoder bridge. Browser controls do not directly drive an SDI transmitter.</p></div>`;
 $$('#content [data-master-take]').forEach(b=>b.onclick=()=>masterTake(b.dataset.masterTake));
 $$('#content [data-master-stop]').forEach(b=>b.onclick=()=>masterStop(b.dataset.masterStop));
 $$('#content [data-master-preview]').forEach(b=>b.onclick=()=>toast('Preview loaded for service '+b.dataset.masterPreview));
}
async function masterTake(id){if(demo){toast('Demo: TAKE TO AIR simulated');return}try{if(state.program==='none')throw Error('Select a Program source first');await api('/workspace/master-control/'+id+'/action',{method:'POST',body:JSON.stringify({action:'take',active_source:state.program,backup_source:'scheduled-playout',emergency_source:'emergency-source'})});toast('TV service is ON AIR');masterControl()}catch(e){toast(e.message,true)}}
async function masterStop(id){if(demo){toast('Demo: service stopped');return}try{await api('/workspace/master-control/'+id+'/action',{method:'POST',body:JSON.stringify({action:'stop'})});toast('TV service stopped');masterControl()}catch(e){toast(e.message,true)}}
async function control(){
 let d={channels:[],states:[],master:[]}, outputs=[];
 if(!demo){try{d=await api('/workspace/master-control')}catch(e){} try{outputs=await api('/workspace/transmission-outputs')}catch(e){}}
 const services=d.rows||[];
 $('#content').innerHTML=`<div class="master-strip"><div><span class="eyebrow">ESSENCE NETWORK • MASTER CONTROL</span><strong>TELEVISION TRANSMISSION</strong><small>Production → Master Program → Playout → Transmission</small></div><div class="master-clock"><span>MASTER</span><b>ON AIR CONTROL</b></div></div>
 <div class="monitor-grid"><div><div class="monitor program"><div class="label">PROGRAM</div><div class="live-dot">ON AIR</div><video id="programVideo" autoplay muted playsinline hidden></video><canvas id="programCanvas"></canvas><div class="empty">${state.program==='none'?'PROGRAM CLEARED':''}</div></div><div class="monitor-footer"><span>${esc(state.program.toUpperCase())}</span><span>MASTER PROGRAM</span></div></div><div><div class="monitor preview"><div class="label">PREVIEW</div><video id="previewVideo" autoplay muted playsinline></video><canvas id="previewCanvas" hidden></canvas><div id="previewGraphic" class="preview-graphic" hidden></div><div class="empty">${!streamFor(state.preview)&&!(state.preview==='media'&&state.mediaUrl)?'SELECT A SOURCE':''}</div></div><div class="monitor-footer"><span>${esc(state.preview.toUpperCase())}</span><span>READY TO TAKE</span></div></div></div>
 <div class="quick-grid"><div class="metric"><small>PROGRAM</small><b>${esc(state.program.toUpperCase())}</b></div><div class="metric"><small>PREVIEW</small><b>${esc(state.preview.toUpperCase())}</b></div><div class="metric"><small>GRAPHICS</small><b>${state.graphics?.onAir?'ON AIR':'OFF'}</b></div><div class="metric"><small>MASTER AUDIO</small><b>${state.camera?'ONLINE':'STANDBY'}</b></div></div>
 <div class="panel station-panel"><div class="page-head"><div><h3>PROGRAM OUTPUT</h3><p class="muted">Publish the mastered Program bus to the configured broadcast engine. This is a programme contribution/output control, not IPTV.</p></div><span id="programFeedStatus" class="status">STOPPED</span></div><div class="form-grid"><label>TV Service<select id="programFeedChannel">${services.map(x=>`<option value="${x.channel.id}">${esc(x.channel.channel_number||'')} • ${esc(x.channel.name)}</option>`).join('')}</select></label><label>Feed mode<select id="programFeedMode"><option value="hls">Local program bus</option><option value="rtmp">RTMP contribution</option></select></label><label class="full">RTMP destination (only for RTMP)<input id="programFeedOutput" placeholder="rtmp://encoder.example/live/program"></label></div><div class="toolbar"><button class="take" id="startProgramFeedBtn">START PROGRAM OUTPUT</button><button class="danger" id="stopProgramFeedBtn">STOP PROGRAM OUTPUT</button></div></div> <div class="panel station-panel"><div class="page-head"><div><h3>TV SERVICES</h3><p class="muted">Select the television service, verify the programme chain, then use the master action.</p></div><button class="ghost" id="refreshMaster">Refresh</button></div><div class="service-grid">${services.map(broadcastServiceCard).join('')||`<div class="panel"><h3>No TV service configured</h3><p class="muted">Open Control Centre → TV Services → New TV service.</p></div>`}</div></div>
 <div class="panel station-panel"><div class="page-head"><div><h3>TRANSMISSION PATH</h3><p class="muted">The software defines the output path; physical SDI/NDI/IP/ASI hardware or an encoder completes the transmission chain.</p></div></div><div class="output-grid"><div><b>1 • PROGRAM</b><span>Vision-mixed master programme</span></div><div><b>2 • GRAPHICS</b><span>Lower thirds, bugs and full-screen keys</span></div><div><b>3 • AUDIO</b><span>Master stereo programme bus</span></div><div><b>4 • TRANSMISSION</b><span>${outputs.length?esc(outputs.length+' configured output(s)'):'Configure station output'}</span></div></div></div>`;
 renderMonitor();
 $('#refreshMaster').onclick=()=>control();
 $('#startProgramFeedBtn').onclick=startProgramFeed;$('#stopProgramFeedBtn').onclick=stopProgramFeed;pollProgramFeed();
 $$('#content [data-master-take]').forEach(b=>b.onclick=()=>masterAction(b.dataset.masterTake,'take'));
 $$('#content [data-master-stop]').forEach(b=>b.onclick=()=>masterAction(b.dataset.masterStop,'stop'));
 $$('#content [data-master-backup]').forEach(b=>b.onclick=()=>masterAction(b.dataset.masterBackup,'backup'));
 $$('#content [data-master-emergency]').forEach(b=>b.onclick=()=>masterAction(b.dataset.masterEmergency,'emergency'));
 $$('#content [data-master-scheduled]').forEach(b=>b.onclick=()=>masterAction(b.dataset.masterScheduled,'scheduled'));
}
function broadcastServiceCard(x){const c=x.channel||{},st=x.state||{},m=x.master||{};return `<div class="service-card"><div><span class="eyebrow">TV SERVICE ${esc(c.service_type||'television').toUpperCase()}</span><h3>${esc(c.channel_number||'—')} • ${esc(c.name||'Unnamed')}</h3><p class="muted">${esc(c.call_sign||'No call sign')} • ${esc(c.video_format||'HD')} • ${esc(c.audio_format||'stereo')}</p></div><div class="service-state ${st.status==='live'?'live':''}">${esc(String(st.status||'offline').toUpperCase())}</div><div class="service-actions"><button class="primary" data-master-take="${c.id}">TAKE TO AIR</button><button class="ghost" data-master-backup="${c.id}">BACKUP</button><button class="danger" data-master-emergency="${c.id}">EMERGENCY</button><button class="ghost" data-master-scheduled="${c.id}">SCHEDULED</button><button class="danger" data-master-stop="${c.id}">STOP SERVICE</button></div><div class="small-note">Output: ${esc(c.transmission_output||'Not configured')} · Automation: ${m.automation_enabled?'ENABLED':'MANUAL'} · Mode: ${esc(m.mode||'scheduled')}</div></div>`}
async function masterAction(id,action){if(action==='take'&&state.program==='none'){toast('Select a Program source before TAKE TO AIR',true);return}if(demo){toast('Demo: '+action.toUpperCase()+' action simulated');return}try{await api('/workspace/master-control/'+id+'/action',{method:'POST',body:JSON.stringify({action,active_source:state.program,backup_source:'scheduled-playout',emergency_source:'emergency-source'})});toast(action==='take'?'TV SERVICE ON AIR':action.toUpperCase()+' selected');control()}catch(e){toast('Master control failed: '+e.message,true)}}

function sources(){ $('#content').innerHTML=`<div class="panel"><div class="page-head"><div><h3>Live Sources</h3><p class="muted">Connect camera/mic, screen share or a local media package.</p></div></div><div class="source-grid"><div class="source-card ${state.camera?'active':''}"><h4>Camera + Mic</h4><p>${state.camera?'ONLINE':'Not connected'}</p><div class="source-actions"><button class="primary" id="cam">${state.camera?'Reconnect':'Connect Camera'}</button></div></div><div class="source-card ${state.screen?'active':''}"><h4>Screen Share</h4><p>${state.screen?'ONLINE':'Not connected'}</p><div class="source-actions"><button class="primary" id="scr">Share Screen</button></div></div><div class="source-card ${state.mediaUrl?'active':''}"><h4>Media Package</h4><p>${state.mediaUrl?'LOADED':'No file loaded'}</p><div class="source-actions"><label class="primary">Choose Video<input id="mediaFile" type="file" accept="video/*" hidden></label></div></div></div></div>`;$('#cam').onclick=enableCamera;$('#scr').onclick=enableScreen;$('#mediaFile').onchange=e=>loadMedia(e.target.files[0])}
function scenes(){ $('#content').innerHTML=`<div class="panel"><div class="page-head"><div><h3>Scene Builder</h3><p class="muted">Build simple, reliable live layouts without a complicated mixer.</p></div><button class="primary" id="applyScene">Use Preview</button></div><div class="scene-grid">${state.scenes.map(s=>`<div class="scene-card ${state.preview===s.source?'active':''}"><h4>${esc(s.name)}</h4><p>${esc(s.desc)}</p><div class="source-actions"><button class="ghost" data-scene="${s.source}">Preview</button></div></div>`).join('')}</div></div>`;$$('[data-scene]').forEach(b=>b.onclick=()=>{state.preview=b.dataset.scene;renderMonitor();toast('Preview: '+b.dataset.scene)});$('#applyScene').onclick=()=>{openView('control');toast('Scene loaded to Preview')}}
async function graphics(){let live=[],channels=[];if(!demo){try{live=await api('/workspace/graphics/on-air');channels=await api('/workspace/channels')}catch{}} $('#content').innerHTML=`<div class="split"><div class="panel"><h3>On-Air Graphics</h3><p class="muted">Prepare a lower third, breaking banner or LIVE bug. Preview first, then TAKE it to Program and, when connected, to the network channel.</p><form class="form" id="gfxForm"><input name="headline" placeholder="Headline / Name" value="${esc(state.graphics?.headline||'')}" required><input name="sub" placeholder="Role / Location" value="${esc(state.graphics?.sub||'')}"><select name="kind"><option value="lower">Lower Third</option><option value="breaking">Breaking News</option><option value="live">LIVE Bug</option></select>${channels.length?`<select name="channel_id">${channels.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select>`:''}<button class="primary">Preview Graphic</button></form><div class="toolbar" style="margin-top:12px"><button class="take" id="takeGraphic">TAKE GRAPHIC</button><button class="danger" id="clearGraphic">CLEAR GRAPHIC</button></div></div><div class="panel"><h3>Graphic Preview</h3><div style="aspect-ratio:16/9;background:#03060d;border:1px solid var(--line);border-radius:12px;position:relative;overflow:hidden"><div id="gfxPreview" style="position:absolute;left:4%;right:4%;bottom:7%;padding:14px 18px;background:linear-gradient(90deg,#111a35ee,#081321dd);border-left:4px solid #8b5cf6"><b id="gpHead">Your headline</b><small id="gpSub" style="display:block;color:#a9b6d1;margin-top:4px">Your subtitle</small></div></div><div class="small-note" style="margin-top:10px">${live.length?live.map(x=>`ON AIR: ${esc(x.name)} • ${esc(x.channel_name)}`).join('<br>'):'No network graphic currently on air.'}</div></div></div>`;$('#gfxForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));state.graphics=o;$('#gpHead').textContent=o.headline;$('#gpSub').textContent=o.sub;toast('Graphic ready in Preview')};$('#takeGraphic').onclick=async()=>{if(!state.graphics){toast('Preview a graphic first',true);return}if(!demo){try{const list=await api('/workspace/graphics');const ch=state.graphics.channel_id||channels[0]?.id;if(!ch)throw Error('No enabled channel');const typeMap={lower:'lower-third',breaking:'headline',live:'bug'};let match=list.find(g=>g.name===state.graphics.headline);const payload={name:state.graphics.headline,type:typeMap[state.graphics.kind]||'lower-third',content:JSON.stringify({headline:state.graphics.headline,sub:state.graphics.sub}),enabled:1};if(!match){match=await api('/workspace/graphics',{method:'POST',body:JSON.stringify(payload)})}else{match=await api('/workspace/graphics/'+match.id,{method:'PUT',body:JSON.stringify(payload)})}await api('/workspace/graphics/'+match.id+'/take',{method:'POST',body:JSON.stringify({channel_id:Number(ch)})});toast('Network graphic TAKEN TO AIR')}catch(e){toast('Network TAKE failed: '+e.message,true)}}state.graphics={...state.graphics,onAir:true};toast('Graphic ON AIR');openView('control')};$('#clearGraphic').onclick=async()=>{if(!demo){try{const ch=state.graphics?.channel_id||channels[0]?.id;if(ch)await api('/workspace/graphics/off',{method:'POST',body:JSON.stringify({channel_id:Number(ch)})})}catch(e){toast('Network clear failed',true)}}state.graphics=null;toast('Graphic cleared');openView('control')}}

function rundown(){ $('#content').innerHTML=`<div class="panel"><div class="page-head"><div><h3>Rundown & Cues</h3><p class="muted">Simple cue stack for the operator. Click a cue to load it into Preview.</p></div><button class="primary" id="nextCue">NEXT CUE</button></div><div class="cue-list">${state.cues.map(c=>`<div class="cue-card"><div class="num">${c.n}</div><div class="grow"><b>${esc(c.name)}</b><div class="small-note">${esc(c.source)}</div></div><span class="status">${esc(c.status)}</span><button class="ghost" data-cue="${c.source}">PREVIEW</button></div>`).join('')}</div></div>`;$$('[data-cue]').forEach(b=>b.onclick=()=>{state.preview=b.dataset.cue;renderMonitor();toast('Cue loaded to Preview')});$('#nextCue').onclick=()=>{const i=state.cues.findIndex(c=>c.status==='READY');const next=state.cues[(i+1)%state.cues.length];state.preview=next.source;renderMonitor();toast('Next cue: '+next.name)}}
function audio(){ $('#content').innerHTML=`<div class="split"><div class="panel"><h3>Audio Mixer</h3><p class="muted">Live browser microphone gain and mute controls.</p><div class="row"><div class="row-main"><b>Presenter Mic</b><div class="meter" style="margin-top:7px"><i id="micMeterBar" style="width:8%"></i></div></div><input id="micGainRange" class="range" type="range" min="0" max="200" value="100" style="max-width:180px"></div><div class="toolbar"><button class="ghost" id="micMute">Mute Mic</button><button class="ghost" id="micRefresh">Refresh Meter</button></div><p class="small-note">Connect Camera + Mic first. Gain is applied through the browser Web Audio pipeline and is included in program recording.</p></div><div class="panel"><h3>Master</h3><p class="muted">Browser program output.</p><div id="masterDb" style="font-size:42px;font-weight:900;margin:15px 0">-∞ dBFS</div><div class="meter"><i id="masterMeter" style="width:4%"></i></div><p class="small-note">Keep peaks below clipping.</p></div></div>`;const r=$('#micGainRange');r.oninput=()=>{if(micGain)micGain.gain.value=Number(r.value)/100};$('#micMute').onclick=()=>{if(micGain){micGain.gain.value=micGain.gain.value?0:1;$('#micMute').textContent=micGain.gain.value?'Mute Mic':'Unmute Mic'}};const tick=()=>{if(micMeter&&$('#micMeterBar')){const a=new Uint8Array(micMeter.frequencyBinCount);micMeter.getByteTimeDomainData(a);let sum=0;for(const v of a){const n=(v-128)/128;sum+=n*n}const rms=Math.sqrt(sum/a.length);const pct=Math.min(100,Math.round(rms*300));$('#micMeterBar').style.width=pct+'%';$('#masterMeter').style.width=Math.max(4,pct)+'%';$('#masterDb').textContent=pct?Math.round(20*Math.log10(pct/100))+' dBFS':'-∞ dBFS'}requestAnimationFrame(tick)};tick()}
async function startProgramFeed(){if(demo){toast('Demo: Program feed simulated');return}if(programStreamActive)return;try{if(!state.programCanvas)openView('control');await new Promise(r=>setTimeout(r,120));const hasSource=(state.program==='camera'&&state.camera)||(state.program==='screen'&&state.screen)||(state.program==='media'&&state.mediaUrl)||(state.program==='pip'&&state.camera);if(!hasSource)throw Error('Select and connect a Program source first');const mode=document.querySelector('#programFeedMode')?.value||'hls';const output=document.querySelector('#programFeedOutput')?.value.trim()||'';const channelId=document.querySelector('#programFeedChannel')?.value||'';const canvas=state.programCanvas;if(!canvas)throw Error('Program canvas is not ready');const stream=canvas.captureStream?.(30);if(!stream)throw Error('Browser does not support program streaming');if(state.camera?.getAudioTracks?.().length)stream.addTrack(state.camera.getAudioTracks()[0]);let opts={};if(MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus'))opts.mimeType='video/webm;codecs=vp9,opus';else if(MediaRecorder.isTypeSupported('video/webm'))opts.mimeType='video/webm';const started=await api('/workspace/program-stream/start',{method:'POST',body:JSON.stringify({mode,output,channel_id:channelId?Number(channelId):null})});if(!started?.stream?.running)throw Error('Server media engine did not start');programStreamRecorder=new MediaRecorder(stream,opts);programStreamActive=true;programStreamChunks=0;programChunkQueue=Promise.resolve();programStreamRecorder.ondataavailable=e=>{if(!e.data.size||!programStreamActive)return;programStreamChunks++;programChunkQueue=programChunkQueue.then(()=>fetch('/api/workspace/program-stream/chunk',{method:'POST',headers:{'Content-Type':e.data.type||'video/webm','Authorization':'Bearer '+token},body:e.data})).catch(err=>toast('Program feed upload failed: '+err.message,true))};programStreamRecorder.onstop=()=>{programStreamRecorder=null};programStreamRecorder.start(1000);toast('PROGRAM FEED is LIVE');setHealth(true,'Program bus is feeding the broadcast engine');pollProgramFeed()}catch(e){programStreamActive=false;try{await api('/workspace/program-stream/stop',{method:'POST'})}catch{}toast('Program feed failed: '+e.message,true)}}
async function stopProgramFeed(){try{if(programStreamRecorder&&programStreamRecorder.state!=='inactive')programStreamRecorder.stop();await api('/workspace/program-stream/stop',{method:'POST'});programStreamActive=false;clearInterval(programStreamTimer);toast('Program feed stopped');setHealth(true,'Production engine ready')}catch(e){toast(e.message,true)}}
async function pollProgramFeed(){clearInterval(programStreamTimer);programStreamTimer=setInterval(async()=>{if(demo)return;try{const x=await api('/workspace/program-stream');programStreamActive=!!x.running;const st=document.querySelector('#programFeedStatus');if(st)st.textContent=x.running?`LIVE • ${x.mode} • ${Math.round((x.bytes||0)/1024)} KB received`:'STOPPED'}catch{}},1500)}
function record(){ $('#content').innerHTML=`<div class="panel"><h3>Program Recording</h3><p class="muted">Record the composed Program canvas locally as WebM, including the browser microphone mix when available.</p><div class="toolbar"><button class="primary" id="startRec">● Start Recording</button><button class="danger" id="stopRec" disabled>■ Stop & Save</button></div><div class="status ${state.recording?'live':''}">${state.recording?'RECORDING':'READY'}</div><p class="small-note" style="margin-top:12px">For server-side master recording or transmission, use a dedicated media engine such as FFmpeg for server-side recording or transmission.</p></div>`;$('#startRec').onclick=startRecording;$('#stopRec').onclick=stopRecording;$('#stopRec').disabled=!state.recording}
async function startRecording(){try{let canvas=state.programCanvas;if(!canvas){openView('control');setTimeout(startRecording,250);return}const stream=canvas.captureStream?.(30);if(!stream){toast('Program recording is not supported in this browser',true);return}if(state.camera?.getAudioTracks?.().length)stream.addTrack(state.camera.getAudioTracks()[0]);state.recordChunks=[];let opts={};if(MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus'))opts.mimeType='video/webm;codecs=vp9,opus';else if(MediaRecorder.isTypeSupported('video/webm'))opts.mimeType='video/webm';state.recorder=new MediaRecorder(stream,opts);state.recorder.ondataavailable=e=>e.data.size&&state.recordChunks.push(e.data);state.recorder.onstop=()=>{const blob=new Blob(state.recordChunks,{type:opts.mimeType||'video/webm'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='essence-program-'+new Date().toISOString().replace(/[:.]/g,'-')+'.webm';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Recording saved')};state.recorder.start(500);state.recording=true;setHealth(true,'Recording program output');openView('record')}catch(e){toast('Recording failed: '+e.message,true)}}
function stopRecording(){if(state.recorder&&state.recorder.state!=='inactive')state.recorder.stop();state.recording=false;record();setHealth(true,'Program engine ready')}


let playoutTimer=null, playoutRows=[];
function fmtTime(v){return v?new Date(v).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}):'--:--:--'}
function countdown(v){const n=Math.max(0,new Date(v).getTime()-Date.now());const s=Math.floor(n/1000);return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function localPlayoutSeed(){const now=Date.now(),t=m=>new Date(now+m*60000).toISOString();return [{id:1,channel_id:1,event_type:'program',title:'Morning Magazine',source:'Studio / Camera 1',start_time:t(-10),end_time:t(20),status:'on-air',priority:10,auto_take:1,transition:'cut'},{id:2,channel_id:1,event_type:'break',title:'Commercial Break A',source:'Break Block 01',start_time:t(20),end_time:t(23),status:'scheduled',priority:5,auto_take:1,transition:'cut'},{id:3,channel_id:1,event_type:'program',title:'News Update',source:'News Playout',start_time:t(23),end_time:t(33),status:'scheduled',priority:8,auto_take:1,transition:'fade'}]}
async function playout(){clearInterval(playoutTimer);let rows=[],channels=[];if(demo){channels=[{id:1,name:'ESSENCE ONE',channel_number:'01',call_sign:'ESSENCE'}];const events=localPlayoutSeed();rows=[{channel:channels[0],current:events[0],next:events[1],events}]}else{try{const d=await api('/workspace/playout-board');rows=d.rows||[];channels=rows.map(r=>r.channel)}catch(e){toast('Playout board unavailable: '+e.message,true)}}playoutRows=rows;$('#content').innerHTML=`<div class="playout-hero"><div><span class="eyebrow">ESSENCE NETWORK • MASTER PLAYOUT</span><h2>Playout Automation</h2><p class="muted">Clock-driven TV rundown with automatic next-event handling, breaks, manual TAKE, HOLD and emergency control.</p></div><div class="air-clock"><small>STATION CLOCK</small><b id="stationClock">${new Date().toLocaleTimeString()}</b></div></div><div class="playout-grid"><div class="panel"><div class="page-head"><div><h3>ON AIR</h3><p class="muted">Current programme and remaining time.</p></div><span class="status live">AUTOMATION READY</span></div><div id="onAirBox">${rows.map(r=>currentCard(r)).join('')||'<p class="muted">No TV service configured.</p>'}</div></div><div class="panel"><div class="page-head"><div><h3>NEXT EVENT</h3><p class="muted">Scheduled next event.</p></div><button class="primary" id="addPlayout">＋ ADD EVENT</button></div><div id="nextBox">${rows.map(r=>nextCard(r)).join('')||'<p class="muted">No next event.</p>'}</div></div></div><div class="panel"><div class="page-head"><div><h3>MASTER TIMELINE</h3><p class="muted">Programmes, live inserts, commercial breaks, adverts and station IDs.</p></div><div class="toolbar"><select id="playoutService">${channels.map(c=>`<option value="${c.id}">${esc(c.channel_number||'')} • ${esc(c.name)}</option>`).join('')}</select><button class="danger" id="emergencyAll">⚠ EMERGENCY</button></div></div><div id="timeline" class="timeline">${rows.map(r=>timeline(r)).join('')||'<p class="muted">Add an event to begin the schedule.</p>'}</div></div><div class="panel"><h3>Operator Rules</h3><div class="output-grid"><div><b>AUTO</b><span>Take scheduled events at their start time.</span></div><div><b>MANUAL TAKE</b><span>Immediately put a selected event on air.</span></div><div><b>HOLD</b><span>Prevent an event from automatic TAKE.</span></div><div><b>EMERGENCY</b><span>Two-step confirmation before takeover.</span></div></div></div>`;$('#addPlayout').onclick=()=>playoutEditor(channels);$('#emergencyAll').onclick=()=>emergencyConfirm(channels[0]?.id);$$('#timeline [data-playout-action]').forEach(b=>b.onclick=()=>playoutAction(b.dataset.id,b.dataset.playoutAction));$$('#timeline [data-edit-playout]').forEach(b=>b.onclick=()=>{const e=playoutRows.flatMap(r=>r.events||[]).find(x=>String(x.id)===String(b.dataset.editPlayout));playoutEditor(channels,e)});playoutTimer=setInterval(playoutTick,1000)}
function currentCard(r){const e=r.current;return `<div class="current-card"><div><span class="eyebrow">${esc(r.channel?.channel_number||'')} • ${esc(r.channel?.name||'SERVICE')}</span><h2>${esc(e?.title||'NO PROGRAMME')}</h2><p class="muted">${esc(e?.event_type||'standby').toUpperCase()} • ${esc(e?.source||'No source')}</p></div><div class="countdown"><small>ENDS IN</small><b data-countdown="${esc(e?.end_time||'')}">${e?countdown(e.end_time):'--:--:--'}</b></div></div>`}
function nextCard(r){const e=r.next;return `<div class="next-card"><div><b>${esc(e?.title||'NO NEXT EVENT')}</b><p class="small-note">${e?fmtTime(e.start_time)+' → '+fmtTime(e.end_time):'Schedule is clear'}</p></div>${e?`<span class="status">${esc(String(e.event_type).toUpperCase())}</span>`:''}</div>`}
function timeline(r){return `<div class="timeline-service"><div class="timeline-head"><b>${esc(r.channel?.channel_number||'')} • ${esc(r.channel?.name||'SERVICE')}</b><span class="small-note">${r.current?'AUTOMATION ACTIVE':'STANDBY'}</span></div>${(r.events||[]).map(e=>`<div class="timeline-row ${e.status==='on-air'?'air':''} ${e.status==='hold'?'hold':''}"><div class="time-col"><b>${fmtTime(e.start_time)}</b><small>${fmtTime(e.end_time)}</small></div><div class="event-main"><div><b>${esc(e.title)}</b> <span class="status ${e.status==='on-air'?'live':''}">${esc(String(e.status||'').toUpperCase())}</span></div><small>${esc(e.event_type)} • ${esc(e.source||'No source')} • ${esc(e.transition||'cut')}</small></div><div class="event-actions"><button class="ghost" data-edit-playout="${e.id}">EDIT</button><button class="primary" data-id="${e.id}" data-playout-action="take">TAKE</button><button class="ghost" data-id="${e.id}" data-playout-action="hold">HOLD</button></div></div>`).join('')}</div>`}
async function playoutTick(){const c=$('#stationClock');if(c)c.textContent=new Date().toLocaleTimeString();$$('[data-countdown]').forEach(x=>x.textContent=countdown(x.dataset.countdown));if(demo)return;const service=$('#playoutService')?.value;if(!service)return;try{const d=await api('/workspace/playout/'+service+'/tick',{method:'POST'});const row=playoutRows.find(r=>Number(r.channel.id)===Number(service));if(row){row.current=d.current;row.next=d.next}}catch{}}
async function playoutAction(id,action){if(action==='take'&&!confirm('Confirm TAKE TO AIR for this event?'))return;if(action==='hold'&&!confirm('Put this event on HOLD?'))return;if(demo){toast('Demo: '+action.toUpperCase());return}try{await api('/workspace/playout-events/'+id+'/action',{method:'POST',body:JSON.stringify({action})});toast(action==='take'?'Event is ON AIR':'Event '+action);playout()}catch(e){toast(e.message,true)}}
async function emergencyConfirm(channelId){if(!channelId)return;if(!confirm('EMERGENCY TAKEOVER? This interrupts scheduled playout.'))return;if(!confirm('Final confirmation: TAKE EMERGENCY SOURCE NOW?'))return;if(demo){toast('Demo: EMERGENCY source selected');return}try{await api('/workspace/master-control/'+channelId+'/action',{method:'POST',body:JSON.stringify({action:'emergency'})});toast('EMERGENCY SOURCE is ON AIR');playout()}catch(e){toast(e.message,true)}}
async function playoutEditor(channels,item=null){if(!channels?.length)return toast('Create a TV service first',true);const now=new Date(),start=item?.start_time?.slice(0,16)||new Date(now.getTime()+60000).toISOString().slice(0,16),end=item?.end_time?.slice(0,16)||new Date(now.getTime()+3600000).toISOString().slice(0,16);const ed=document.createElement('div');ed.className='modal';ed.innerHTML=`<div class="panel modal-card"><div class="page-head"><div><h3>${item?'Edit':'Add'} Playout Event</h3><p class="muted">Schedule programmes, live events, breaks, adverts and station IDs.</p></div><button class="ghost" id="closePlayout">Close</button></div><form class="form" id="playoutForm"><label>TV Service<select name="channel_id">${channels.map(c=>`<option value="${c.id}" ${item&&Number(item.channel_id)===Number(c.id)?'selected':''}>${esc(c.channel_number||'')} • ${esc(c.name)}</option>`).join('')}</select></label><label>Event type<select name="event_type"><option value="program">Programme</option><option value="live">Live event</option><option value="break">Commercial break</option><option value="advert">Advert</option><option value="station-id">Station ID</option><option value="emergency">Emergency</option></select></label><label>Title<input name="title" required value="${esc(item?.title||'New Programme')}"></label><label>Source / media<input name="source" value="${esc(item?.source||'')}" placeholder="File, live source, studio or break block"></label><div class="form-grid"><label>Start<input type="datetime-local" name="start_time" value="${esc(start)}" required></label><label>End<input type="datetime-local" name="end_time" value="${esc(end)}" required></label></div><div class="form-grid"><label>Priority<input type="number" name="priority" min="0" max="100" value="${Number(item?.priority||0)}"></label><label>Transition<select name="transition"><option value="cut">Cut</option><option value="fade">Fade</option><option value="dip">Dip</option><option value="manual">Manual</option></select></label></div><label class="check"><input type="checkbox" name="auto_take" ${item&&!Number(item.auto_take)?'':'checked'}> Automatic TAKE at scheduled time</label><label>Notes<textarea name="notes" rows="3">${esc(item?.notes||'')}</textarea></label><button class="primary">${item?'Save Event':'Schedule Event'}</button></form></div>`;document.body.appendChild(ed);ed.querySelector('#closePlayout').onclick=()=>ed.remove();ed.querySelector('#playoutForm').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),o=Object.fromEntries(f);o.channel_id=Number(o.channel_id);o.auto_take=ev.target.elements.auto_take.checked?1:0;try{if(demo){ed.remove();toast('Demo: event scheduled');playout();return}await api('/workspace/playout-events'+(item?'/'+item.id:''),{method:item?'PUT':'POST',body:JSON.stringify(o)});ed.remove();toast(item?'Event updated':'Event scheduled');playout()}catch(e){toast(e.message,true)}}}

async function engine(){
 let outputs=[]; if(!demo){try{outputs=await api('/workspace/transmission-outputs')}catch{}}
 $('#content').innerHTML=`<div class="panel"><div class="page-head"><div><span class="eyebrow">STATION ENGINEERING</span><h3>Transmission Outputs</h3><p class="muted">Configure the physical/network interface that carries each television service. This page is the station output map — not an IPTV channel list.</p></div><button class="primary" id="newOutput">＋ ADD OUTPUT</button></div><div class="output-list">${outputs.map(o=>`<div class="output-card"><div><span class="eyebrow">${esc(String(o.type||'ip').toUpperCase())}</span><h3>${esc(o.name)}</h3><p class="muted">${esc(o.channel_name||'')} • ${esc(o.channel_number||'')} • ${esc(o.format||'')} • ${esc(o.audio_format||'')}</p></div><div><b>${Number(o.enabled)?'ENABLED':'DISABLED'}</b><small>${esc(o.endpoint||'Endpoint not set')}</small></div><div class="service-actions"><button class="ghost" data-test-output="${o.id}">TEST</button><button class="primary" data-activate-output="${o.id}">ACTIVATE</button><button class="ghost" data-edit-output="${o.id}">Edit</button><button class="danger" data-del-output="${o.id}">Delete</button></div><div class="small-note output-status" id="outputStatus${o.id}">Ready</div></div>`).join('')||'<div class="panel"><h3>No transmission outputs</h3><p class="muted">Add the station output that your broadcast I/O or encoder will use.</p></div>'}</div></div><div class="panel"><h3>Broadcast chain</h3><div class="output-grid"><div><b>PROGRAM</b><span>Vision mixer / master programme</span></div><div><b>PLAYOUT</b><span>Scheduled files and live events</span></div><div><b>MASTER CONTROL</b><span>Take, backup, emergency and restore</span></div><div><b>TRANSMITTER</b><span>External broadcast I/O / encoder</span></div></div><p class="small-note" style="margin-top:12px">The Studio does not claim to be an RF transmitter. It prepares and controls the station programme feed and its configured transmission interfaces.</p></div>`;
 $('#newOutput').onclick=()=>outputEditor();
 $$('#content [data-edit-output]').forEach(b=>b.onclick=async()=>{const x=outputs.find(v=>Number(v.id)===Number(b.dataset.editOutput));outputEditor(x)});
$$('#content [data-test-output]').forEach(b=>b.onclick=async()=>{const el=$('#outputStatus'+b.dataset.testOutput);el.textContent='Testing…';try{const r=await api('/workspace/transmission-outputs/'+b.dataset.testOutput+'/test',{method:'POST'});el.textContent=(r.test.ready?'✓ READY • ':'⚠ NOT READY • ')+r.test.message;toast(r.test.message,!r.test.ready)}catch(e){el.textContent='✕ '+e.message;toast(e.message,true)}});
$$('#content [data-activate-output]').forEach(b=>b.onclick=async()=>{const el=$('#outputStatus'+b.dataset.activateOutput);el.textContent='Activating…';try{const r=await api('/workspace/transmission-outputs/'+b.dataset.activateOutput+'/activate',{method:'POST'});el.textContent='● ACTIVE • '+r.state.message;toast('Transmission output activated')}catch(e){el.textContent='✕ '+e.message;toast(e.message,true)}});
 $$('#content [data-del-output]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this transmission output?'))return;try{await api('/workspace/transmission-outputs/'+b.dataset.delOutput,{method:'DELETE'});toast('Output deleted');engine()}catch(e){toast(e.message,true)}});
}
async function outputEditor(item=null){let channels=[];if(!demo){try{channels=await api('/workspace/channels')}catch{}}if(!channels.length&&item?.channel_id)channels=[{id:item.channel_id,name:item.channel_name||'Current service'}];const ed=document.createElement('div');ed.className='modal';ed.innerHTML=`<div class="panel modal-card"><div class="page-head"><div><h3>${item?'Edit':'Add'} transmission output</h3><p class="muted">Configure where the master programme leaves the station.</p></div><button class="ghost" id="closeOutput">Close</button></div><form class="form" id="outputForm"><label>TV Service<select name="channel_id" required>${channels.map(c=>`<option value="${c.id}" ${item&&Number(item.channel_id)===Number(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Output name<input name="name" required value="${esc(item?.name||'Primary Transmission')}</label><label>Interface<select name="type"><option value="sdi" ${item?.type==='sdi'?'selected':''}>SDI</option><option value="ndi" ${item?.type==='ndi'?'selected':''}>NDI</option><option value="ip" ${!item||item?.type==='ip'?'selected':''}>IP / Encoder</option><option value="asi" ${item?.type==='asi'?'selected':''}>ASI</option><option value="file" ${item?.type==='file'?'selected':''}>File / Archive</option></select></label><label>Endpoint / Device<input name="endpoint" value="${esc(item?.endpoint||'')}" placeholder="SDI-1 / NDI source / encoder address"></label><label>Video format<select name="format"><option value="1080p25">1080p25</option><option value="1080i50">1080i50</option><option value="720p50">720p50</option><option value="576i25">576i25</option></select></label><label>Audio<select name="audio_format"><option value="stereo">Stereo</option><option value="mono">Mono</option></select></label><label class="check"><input type="checkbox" name="enabled" ${!item||Number(item.enabled)?'checked':''}> Enabled</label><label class="check"><input type="checkbox" name="primary_output" ${item&&Number(item.primary_output)?'checked':''}> Primary output</label><label>Notes<textarea name="notes" rows="3">${esc(item?.notes||'')}</textarea></label><button class="primary">${item?'Save output':'Create output'}</button></form></div>`;document.body.appendChild(ed);ed.querySelector('#closeOutput').onclick=()=>ed.remove();ed.querySelector('#outputForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f);o.enabled=e.target.elements.enabled.checked?1:0;o.primary_output=e.target.elements.primary_output.checked?1:0;o.channel_id=Number(o.channel_id);try{await api('/workspace/transmission-outputs'+(item?'/'+item.id:''),{method:item?'PUT':'POST',body:JSON.stringify(o)});ed.remove();toast(item?'Output updated':'Output created');engine()}catch(x){toast(x.message,true)}}}

async function settings(){let apiStatus='Local mode';if(!demo){try{const h=await api('/health');apiStatus=`API ${h.version} • ${new Date(h.time).toLocaleTimeString()}`}catch{apiStatus='API unavailable — local controls still work'}}$('#content').innerHTML=`<div class="panel"><h3>Studio Settings</h3><p class="muted">${esc(apiStatus)}</p><div class="form-grid"><label>Operator name<input value="${esc(me?.email||'Demo Operator')}" disabled></label><label>Keyboard shortcut<input value="Space = TAKE" disabled></label><label class="full">Public player<input value="/" disabled></label></div></div>`}
function openView(v){view=v;$('#viewTitle').textContent={control:'Master Control',sources:'Sources',scenes:'Scenes',graphics:'Graphics',rundown:'Rundown',playout:'Playout Automation',audio:'Audio',record:'Master Record',engine:'Transmission Outputs',settings:'Station Settings'}[v]||'Production';$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));({control,sources,scenes,graphics,rundown,playout,audio,record,engine,settings}[v]||control)()}
function bind(){ $$('#nav button').forEach(b=>b.onclick=()=>openView(b.dataset.view));$('#takeBtn').onclick=take;$('#clearBtn').onclick=clearProgram;$('#logout').onclick=()=>{localStorage.removeItem('essenceWorkspaceToken');token=null;showLogin()};$('#loginBtn').onclick=login;$('#demoBtn').onclick=openDemo;$('#password').onkeydown=e=>{if(e.key==='Enter')login()};$('#publicBtn').onclick=()=>window.open('/','_blank');document.addEventListener('keydown',e=>{if(e.code==='Space'&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();take()}});setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString(),1000);start()}
bind();
